const listStockAdjustments = `-- name: ListStockAdjustments :many
SELECT a.id, a.uuid, a.organization_id, a.brand_id, a.adjustment_no, a.warehouse_id, a.type, a.reason_code, a.note, a.source, a.status, a.total_quantity, a.total_meters, a.requires_second_approval, a.created_by_user_id, a.submitted_by_user_id, a.submitted_at, a.approved_by_user_id, a.posted_at, a.cancelled_by_user_id, a.cancelled_at, a.cancel_reason, a.created_at, a.updated_at FROM stock_adjustments a
WHERE a.organization_id = $1
  AND (COALESCE(cardinality($2::text[]), 0) = 0 OR a.status = ANY ($2::text[]))
  AND (COALESCE(cardinality($3::text[]), 0) = 0 OR a.type = ANY ($3::text[]))
  AND (COALESCE(cardinality($4::text[]), 0) = 0 OR a.source = ANY ($4::text[]))
  AND (COALESCE(cardinality($5::uuid[]), 0) = 0
       OR EXISTS (SELECT 1 FROM warehouses fw
                  WHERE fw.id = a.warehouse_id AND fw.uuid = ANY ($5::uuid[])))
  AND (COALESCE(cardinality($6::uuid[]), 0) = 0 OR a.uuid = ANY ($6::uuid[]))
  AND ($7::timestamptz IS NULL OR a.created_at >= $7::timestamptz)
  AND ($8::timestamptz IS NULL OR a.created_at < $8::timestamptz)
  AND ($9::text IS NULL
       OR a.adjustment_no ILIKE '%' || $9::text || '%'
       OR a.note ILIKE '%' || $9::text || '%'
       OR a.reason_code ILIKE '%' || $9::text || '%')
ORDER BY
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'created_at' THEN a.created_at END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'created_at' THEN a.created_at END END DESC,
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'adjustment_no' THEN a.adjustment_no END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'adjustment_no' THEN a.adjustment_no END END DESC,
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'type' THEN a.type END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'type' THEN a.type END END DESC,
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'status' THEN
    CASE a.status WHEN 'draft' THEN 1 WHEN 'pending_approval' THEN 2 WHEN 'posted' THEN 3 ELSE 4 END END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'status' THEN
    CASE a.status WHEN 'draft' THEN 1 WHEN 'pending_approval' THEN 2 WHEN 'posted' THEN 3 ELSE 4 END END END DESC,
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'total_quantity' THEN a.total_quantity END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'total_quantity' THEN a.total_quantity END END DESC,
  CASE WHEN NOT $10::bool THEN CASE $11::text WHEN 'total_meters' THEN a.total_meters END END ASC,
  CASE WHEN $10::bool THEN CASE $11::text WHEN 'total_meters' THEN a.total_meters END END DESC,
  CASE WHEN $10::bool THEN a.id END DESC,
  a.id ASC
LIMIT $13 OFFSET $12
`

